head.b:skin:
/*
<Variable name="backgroundColor" description="Background color" type="color" default="#05080a" value="#05080a"/>
<Variable name="accentColor" description="Phosphor accent color" type="color" default="#3dffa0" value="#3dffa0"/>
<Variable name="textColor" description="Text color" type="color" default="#c6dcd2" value="#c6dcd2"/>
<Variable name="panelColor" description="Terminal panel color" type="color" default="#0a1113" value="#0a1113"/>
*/

:root {
  --bg:        #05080a;
  --bg-2:      #080d0f;
  --panel:     #0a1113;
  --panel-2:   #0d1518;
  --line:      #17302c;
  --line-2:    #23473e;
  --grn:       #3dffa0;
  --grn-dim:   #2ad486;
  --grn-dark:  #0e2a1e;
  --cyan:      #39e6ff;
  --red:       #ff3b5c;
  --amber:     #ffc857;
  --txt:       #c6dcd2;
  --muted:     #6f8f82;
  --mono:      'Share Tech Mono', ui-monospace, 'Cascadia Code', 'JetBrains Mono', Consolas, 'Courier New', monospace;
  --sans:      'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --glow:      0 0 14px rgba(61, 255, 160, .35);
  --glow-soft: 0 0 8px rgba(61, 255, 160, .18);
  --radius:    2px;
  --w:         1180px;
}
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--bg); color: var(--txt); font-family: var(--sans); font-size: 15px; line-height: 1.7; -webkit-font-smoothing: antialiased; overflow-x: hidden; }
body::before { content: ''; position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background:
    radial-gradient(900px 420px at 50% -80px, rgba(61,255,160,.07), transparent 70%),
    linear-gradient(rgba(61,255,160,.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(61,255,160,.025) 1px, transparent 1px);
  background-size: 100% 100%, 44px 44px, 44px 44px; }
h1, h2, h3, h4, h5 { font-family: var(--mono); line-height: 1.3; margin: 0 0 .6em; font-weight: 400; }
a { color: var(--grn); text-decoration: none; transition: color .15s ease, text-shadow .15s ease, border-color .15s ease; }
a:hover { color: var(--grn); text-shadow: var(--glow-soft); }
img { max-width: 100%; }
::selection { background: var(--grn); color: #04120b; }

.crt-lines { position: fixed; inset: 0; z-index: 9996; pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(0,0,0,.25) 0px, rgba(0,0,0,.25) 1px, transparent 1px, transparent 3px);
  opacity: .55; animation: crt-flicker 4s infinite steps(60); }
.crt-vignette { position: fixed; inset: 0; z-index: 9995; pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 58%, rgba(0,0,0,.6) 100%); }
@keyframes crt-flicker { 0%,93%{opacity:.55} 94%{opacity:.48} 96%{opacity:.6} 98%{opacity:.5} 100%{opacity:.55} }

#progress-bar { position: fixed; top: 0; left: 0; height: 3px; width: 0; background: linear-gradient(90deg, var(--grn-dim), var(--grn), var(--cyan)); box-shadow: var(--glow); z-index: 1002; }
#back-to-top { position: fixed; right: 18px; bottom: 18px; z-index: 1001; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; background: rgba(8,13,15,.9); border: 1px solid var(--line-2); color: var(--grn); font-family: var(--mono); font-size: 1.1rem; cursor: pointer; opacity: 0; visibility: hidden; transform: translateY(10px); transition: all .2s ease; }
#back-to-top.show { opacity: 1; visibility: visible; transform: none; }
#back-to-top:hover { background: var(--grn); color: #04120b; box-shadow: var(--glow); }

.site-header { position: sticky; top: 0; z-index: 1000; background: rgba(5,8,10,.86); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border-bottom: 1px solid var(--line); }
.header-inner { max-width: var(--w); margin: 0 auto; padding: .7rem 1.2rem; display: flex; align-items: center; gap: 1rem; flex-wrap: wrap; position: relative; }
.header-section { flex: 0 0 auto; }
.header-widget { display: flex; flex-direction: column; gap: 2px; }
.logo { display: inline-flex; align-items: center; gap: .6rem; line-height: 1; }
.logo img { height: 38px; width: auto; display: block; }
.logo-text { font-family: var(--mono); font-size: 1.45rem; letter-spacing: .06em; color: var(--grn); text-shadow: var(--glow-soft); }
.tagline { margin: 0; font-family: var(--mono); font-size: .68rem; color: var(--muted); letter-spacing: .12em; text-transform: uppercase; }
.nav-section { margin-left: auto; }
.nav-links { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: .2rem; flex-wrap: wrap; font-family: var(--mono); font-size: .82rem; }
.nav-links a { display: inline-block; padding: .45rem .8rem; color: var(--txt); text-transform: lowercase; letter-spacing: .05em; border: 1px solid transparent; }
.nav-links a .np { color: var(--grn-dim); opacity: 0; transition: opacity .15s; }
.nav-links a:hover { color: var(--grn); background: var(--grn-dark); border-color: var(--line-2); text-shadow: none; }
.nav-links a:hover .np { opacity: 1; }
.nav-toggle { display: none; margin-left: auto; background: var(--panel); border: 1px solid var(--line-2); color: var(--grn); font-family: var(--mono); font-size: 1rem; padding: .45rem .8rem; cursor: pointer; line-height: 1; }
.nav-toggle:hover { background: var(--grn-dark); }

.layout { max-width: var(--w); margin: 1.6rem auto; padding: 0 1.2rem; display: grid; grid-template-columns: minmax(0,1fr) 320px; gap: 1.5rem; position: relative; z-index: 1; align-items: start; }
.content { min-width: 0; }
.sidebar { min-width: 0; }

.terminal-card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); position: relative; }
.terminal-card::after { content: ''; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, rgba(61,255,160,.035), transparent 220px); }

.btn-term { display: inline-block; font-family: var(--mono); font-size: .82rem; letter-spacing: .04em; color: var(--grn); background: transparent; border: 1px solid var(--line-2); padding: .6rem 1.1rem; cursor: pointer; transition: all .15s ease; text-transform: lowercase; line-height: 1.2; }
.btn-term:hover { background: var(--grn); color: #04120b; border-color: var(--grn); text-shadow: none; box-shadow: var(--glow); }
.btn-term.primary { border-color: var(--grn-dim); }

.glitch { position: relative; display: inline-block; }
.glitch::before, .glitch::after { content: attr(data-text); position: absolute; left: 0; top: 0; width: 100%; overflow: hidden; pointer-events: none; }
.glitch::before { color: var(--red); animation: glitch-a 2.8s infinite steps(2,end); }
.glitch::after { color: var(--cyan); animation: glitch-b 3.4s infinite steps(2,end); }
.glitch.soft::before, .glitch.soft::after { opacity: 0; }
.glitch.soft:hover::before { opacity: .85; }
.glitch.soft:hover::after { opacity: .85; }
@keyframes glitch-a { 0%{clip-path:inset(18% 0 62% 0);transform:translate(-2px,-1px)} 15%{clip-path:inset(72% 0 8% 0);transform:translate(2px,1px)} 30%{clip-path:inset(42% 0 38% 0);transform:translate(-1px,1px)} 45%{clip-path:inset(8% 0 78% 0);transform:translate(2px,-1px)} 60%{clip-path:inset(58% 0 22% 0);transform:translate(-2px,0)} 75%{clip-path:inset(30% 0 52% 0);transform:translate(1px,1px)} 100%{clip-path:inset(80% 0 4% 0);transform:translate(-1px,-1px)} }
@keyframes glitch-b { 0%{clip-path:inset(64% 0 12% 0);transform:translate(2px,1px)} 20%{clip-path:inset(12% 0 70% 0);transform:translate(-2px,-1px)} 40%{clip-path:inset(48% 0 30% 0);transform:translate(1px,-1px)} 60%{clip-path:inset(26% 0 56% 0);transform:translate(-1px,1px)} 80%{clip-path:inset(78% 0 6% 0);transform:translate(2px,0)} 100%{clip-path:inset(38% 0 44% 0);transform:translate(-2px,1px)} }
.blink { animation: blink 1.1s steps(1) infinite; }
@keyframes blink { 0%,55%{opacity:1} 56%,100%{opacity:0} }

.hero { margin-bottom: 1.6rem; overflow: hidden; }
.hero-bar { display: flex; align-items: center; gap: .45rem; padding: .55rem .9rem; border-bottom: 1px solid var(--line); background: var(--panel-2); font-family: var(--mono); font-size: .75rem; color: var(--muted); }
.hero-bar .dot { width: 10px; height: 10px; border-radius: 50%; }
.hero-bar .dot.r { background: var(--red); }
.hero-bar .dot.y { background: var(--amber); }
.hero-bar .dot.g { background: var(--grn); box-shadow: var(--glow-soft); }
.hero-bar .bar-title { margin-left: .5rem; }
.hero-body { padding: 2rem 1.8rem 1.8rem; }
.hero-line { font-family: var(--mono); font-size: .85rem; color: var(--muted); margin: 0 0 .4rem; }
.hero-line .prompt { color: var(--grn); }
.hero-line .path { color: var(--cyan); }
.hero h1 { font-size: clamp(1.9rem,5.5vw,3.4rem); color: var(--grn); text-shadow: var(--glow); margin: .3rem 0 .5rem; letter-spacing: .04em; line-height: 1.05; }
.hero-tag { font-family: var(--mono); color: var(--cyan); font-size: .85rem; margin: 0 0 1rem; letter-spacing: .05em; }
.hero-desc { max-width: 640px; color: var(--muted); margin: 0 0 1.4rem; }
.hero-desc em { color: var(--txt); font-style: normal; border-bottom: 1px dashed var(--line-2); }
.hero-actions { display: flex; flex-wrap: wrap; gap: .8rem; margin-bottom: 1rem; }
.hero-cursor { font-family: var(--mono); color: var(--grn); margin: 0; font-size: 1rem; }
.hero-cursor .cursor { background: var(--grn); color: transparent; animation: blink 1.1s steps(1) infinite; }

.feed-heading { font-family: var(--mono); font-size: .95rem; color: var(--muted); margin: 0 0 1rem; letter-spacing: .04em; border-bottom: 1px dashed var(--line); padding-bottom: .6rem; }
.feed-heading .cmd { color: var(--grn); }

.post-card { display: grid; grid-template-columns: 300px minmax(0,1fr); margin-bottom: 1.4rem; overflow: hidden; transition: border-color .2s ease, box-shadow .2s ease, transform .2s ease; }
.post-card:hover { border-color: var(--grn-dim); box-shadow: 0 0 28px rgba(61,255,160,.09); }
.card-thumb { position: relative; display: block; background: var(--bg-2); overflow: hidden; min-height: 190px; }
.card-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; aspect-ratio: 16/10; transition: transform .35s ease, filter .35s ease; filter: saturate(.85) contrast(1.05); }
.post-card:hover .card-thumb img { transform: scale(1.04); filter: saturate(1) contrast(1.1); }
.card-thumb::after { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(5,8,10,.55), transparent 55%); pointer-events: none; }
.no-thumb { display: flex; align-items: center; justify-content: center; height: 100%; min-height: 190px; font-family: var(--mono); color: var(--line-2); font-size: .9rem; background: repeating-linear-gradient(45deg, var(--bg-2) 0 12px, #060b0d 12px 24px); }
.card-badge { position: absolute; top: .7rem; left: .7rem; z-index: 2; font-family: var(--mono); font-size: .72rem; letter-spacing: .1em; background: var(--grn); color: #04120b; padding: .2rem .55rem; font-weight: 700; box-shadow: var(--glow-soft); }
.card-body { padding: 1.1rem 1.3rem 1.25rem; display: flex; flex-direction: column; }
.card-meta { font-family: var(--mono); font-size: .72rem; color: var(--muted); letter-spacing: .06em; margin-bottom: .45rem; display: flex; flex-wrap: wrap; gap: .35rem 1rem; align-items: center; }
.card-meta a { color: var(--cyan); }
.card-meta .m-sep { color: var(--line-2); }
.post-card .post-title { font-size: 1.12rem; margin: 0 0 .55rem; }
.post-card .post-title a { color: var(--grn); }
.post-card .post-title a:hover { text-shadow: var(--glow); }
.post-snippet { color: var(--muted); font-size: .88rem; line-height: 1.65; margin: 0 0 1rem; flex: 1; }
.read-more { margin-top: auto; align-self: flex-start; }

.post-single { overflow: hidden; }
.post-header { padding: 1.5rem 1.6rem 1.2rem; border-bottom: 1px dashed var(--line-2); }
.breadcrumb { font-family: var(--mono); font-size: .75rem; color: var(--muted); margin: 0 0 .8rem; letter-spacing: .04em; }
.breadcrumb a { color: var(--cyan); }
.breadcrumb .sep { color: var(--line-2); margin: 0 .35rem; }
.post-single .post-title { font-size: clamp(1.4rem,3.4vw,2rem); color: var(--grn); text-shadow: var(--glow-soft); margin: 0 0 .8rem; }
.post-meta { font-family: var(--mono); font-size: .76rem; color: var(--muted); display: flex; flex-wrap: wrap; gap: .4rem 1.2rem; align-items: center; }
.post-meta a { color: var(--cyan); }
.post-meta .meta-dot { color: var(--grn-dim); }
.post-body { padding: 1.6rem; font-size: .95rem; }
.post-body > *:first-child { margin-top: 0; }
.post-body p { margin: 0 0 1.05em; }
.post-body h2, .post-body h3, .post-body h4 { color: var(--grn); margin: 1.6em 0 .7em; font-size: 1.15rem; }
.post-body h2::before { content: '$ '; color: var(--grn-dim); }
.post-body h3::before { content: '>> '; color: var(--grn-dim); }
.post-body a { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--line-2); }
.post-body a:hover { text-decoration-color: var(--grn); }
.post-body ul, .post-body ol { padding-left: 1.4rem; margin: 0 0 1.1em; }
.post-body li { margin: .3em 0; }
.post-body li::marker { color: var(--grn-dim); }
.post-body img, .post-body video, .post-body iframe { max-width: 100%; height: auto; border: 1px solid var(--line); background: var(--bg-2); }
.post-body .separator { margin: 1.4rem auto; text-align: center; }
.post-body .separator a { text-decoration: none; }
.post-body img { display: block; margin: 1.4rem auto; transition: border-color .2s, box-shadow .2s; }
.post-body img:hover { border-color: var(--grn-dim); box-shadow: 0 0 26px rgba(61,255,160,.12); }
.post-body blockquote { margin: 1.3em 0; padding: .8rem 1.2rem; border-left: 3px solid var(--grn-dim); background: var(--panel-2); color: var(--txt); font-style: italic; }
.post-body code { font-family: var(--mono); font-size: .85em; background: #020504; color: var(--grn); border: 1px solid var(--line); padding: .12em .4em; border-radius: var(--radius); }
.post-body pre { background: #020504; border: 1px solid var(--line); padding: 1rem; overflow-x: auto; margin: 1.2em 0; }
.post-body pre code { border: 0; padding: 0; background: none; }
.post-body hr { border: 0; height: 0; border-top: 1px dashed var(--line-2); margin: 1.8em 0; }
.post-body table { width: 100%; border-collapse: collapse; margin: 1.3em 0; font-family: var(--mono); font-size: .82rem; display: table; }
.post-body th, .post-body td { border: 1px solid var(--line); padding: .55rem .8rem; text-align: left; vertical-align: top; }
.post-body th { background: var(--panel-2); color: var(--grn); font-weight: 400; }
.post-body td:first-child { color: var(--cyan); width: 1%; white-space: nowrap; }
.post-footer { padding: 1.1rem 1.6rem 1.4rem; border-top: 1px dashed var(--line-2); display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; justify-content: space-between; }
.post-labels { display: flex; flex-wrap: wrap; gap: .45rem; }
.label-tag { font-family: var(--mono); font-size: .74rem; color: var(--cyan); border: 1px solid var(--line); padding: .2rem .6rem; transition: all .15s; }
.label-tag:hover { color: #04120b; background: var(--cyan); border-color: var(--cyan); text-shadow: none; }
.share-row { display: flex; align-items: center; flex-wrap: wrap; gap: .4rem; }
.share-label { font-family: var(--mono); font-size: .74rem; color: var(--muted); margin-right: .2rem; }
.share-link { font-family: var(--mono); font-size: .72rem; border: 1px solid var(--line-2); color: var(--grn); padding: .25rem .6rem; text-transform: uppercase; letter-spacing: .06em; }
.share-link:hover { background: var(--grn); color: #04120b; border-color: var(--grn); text-shadow: none; }

.related-feed { margin-top: 1.4rem; padding: 1.3rem 1.4rem; display: none; }
.related-title { font-size: .95rem; color: var(--grn); margin-bottom: 1rem; }
.related-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: .9rem; }
.related-item { display: block; border: 1px solid var(--line); background: var(--bg-2); overflow: hidden; transition: border-color .2s, box-shadow .2s; }
.related-item:hover { border-color: var(--grn-dim); box-shadow: var(--glow-soft); text-shadow: none; }
.ri-thumb { position: relative; aspect-ratio: 16/9; overflow: hidden; background: var(--bg-2); }
.ri-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; filter: saturate(.85); transition: transform .3s; }
.related-item:hover .ri-thumb img { transform: scale(1.05); filter: saturate(1); }
.ri-no { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-family: var(--mono); font-size: .7rem; color: var(--line-2); background: repeating-linear-gradient(45deg, var(--bg-2) 0 10px, #060b0d 10px 20px); }
.ri-title { display: block; padding: .6rem .7rem; font-family: var(--mono); font-size: .74rem; line-height: 1.45; color: var(--txt); }
.related-item:hover .ri-title { color: var(--grn); }

.comments-wrap { margin-top: 1.4rem; padding: 1.4rem 1.6rem; }
.comments h3, .comments h4 { color: var(--grn); font-size: 1.05rem; margin: 1.2em 0 .8em; }
.comments h3::before, .comments h4::before { content: '# '; color: var(--grn-dim); }
.comment-thread { list-style: none; margin: 0; padding: 0; }
.comment { border: 1px solid var(--line); background: var(--bg-2); padding: 1rem 1.1rem; margin: 0 0 .9rem; }
.comment-header { display: flex; flex-wrap: wrap; gap: .25rem .8rem; align-items: baseline; margin-bottom: .45rem; }
.comment-author { font-family: var(--mono); font-size: .85rem; }
.comment-author a, .comment-author .author { color: var(--cyan); }
.comment-meta { font-family: var(--mono); font-size: .7rem; color: var(--muted); }
.comment-content { margin-top: .5rem; font-size: .9rem; }
.comment-content p { margin: .4em 0; }
.comment-replies { margin: .85rem 0 0 1rem; padding-left: 1rem; border-left: 2px solid var(--line); list-style: none; }
.comment.deleted .comment-content { color: var(--muted); font-style: italic; }
.comment-form, .comment-replybox-form { margin-top: 1rem; }
.comments input[type='text'], .comments input[type='email'], .comments input[type='url'], .comments textarea {
  width: 100%; background: #03070a; border: 1px solid var(--line-2); color: var(--txt);
  font-family: var(--mono); font-size: .85rem; padding: .6rem .8rem; margin: .35rem 0;
  border-radius: var(--radius); outline: none; transition: border-color .15s, box-shadow .15s; }
.comments input:focus, .comments textarea:focus { border-color: var(--grn-dim); box-shadow: 0 0 0 1px rgba(61,255,160,.25); }
.comments textarea { min-height: 110px; resize: vertical; }
.comment-editor-frame { width: 100%; min-height: 210px; background: #f4faf6; border: 1px solid var(--line-2); border-radius: var(--radius); }
.comments .comment-form-button, .comments input[type='submit'], .comments button[type='submit'] {
  width: auto; background: transparent; color: var(--grn); border: 1px solid var(--grn-dim);
  font-family: var(--mono); text-transform: lowercase; padding: .55rem 1.2rem; cursor: pointer; margin-top: .4rem; transition: all .15s; }
.comments .comment-form-button:hover, .comments input[type='submit']:hover { background: var(--grn); color: #04120b; box-shadow: var(--glow); }
.comment-notify { font-family: var(--mono); font-size: .76rem; color: var(--muted); display: block; margin: .6rem 0; }

.view-header { padding: 1.4rem 1.6rem; margin-bottom: 1.5rem; }
.view-header .vh-line { font-family: var(--mono); color: var(--muted); font-size: .82rem; margin: 0 0 .5rem; }
.view-header h1 { font-size: 1.5rem; color: var(--grn); margin: 0 0 .6rem; word-break: break-word; }
.view-header.is-error h1 { color: var(--red); text-shadow: 0 0 14px rgba(255,59,92,.3); }
.view-header p { color: var(--muted); margin: 0 0 1rem; }
.view-header .result-count { color: var(--cyan); font-family: var(--mono); font-size: .78rem; }
.status-msg-wrap { border: 1px dashed var(--line-2); background: var(--panel-2); padding: 1rem 1.3rem; margin-bottom: 1.4rem; font-family: var(--mono); font-size: .85rem; color: var(--amber); }
.blog-pager { display: flex; justify-content: space-between; align-items: center; gap: .8rem; margin: 1.6rem 0; flex-wrap: wrap; }
.blog-pager a { font-family: var(--mono); font-size: .8rem; }
.blog-pager .pager-home { color: var(--muted); border-color: var(--line); }
.blog-pager .pager-older { margin-left: auto; }

.widget { background: var(--panel); border: 1px solid var(--line); margin-bottom: 1.4rem; position: relative; }
.widget-title, .widget > h2, .widget > h3 { font-family: var(--mono); font-size: .82rem; font-weight: 400; color: var(--grn); letter-spacing: .08em; margin: 0; padding: .7rem 1rem; border-bottom: 1px solid var(--line); background: var(--panel-2); text-transform: lowercase; }
.widget-title::before, .widget > h2::before, .widget > h3::before { content: '~/'; color: var(--muted); }
.widget-content { padding: .9rem 1rem; }
.term-search { display: flex; align-items: stretch; gap: 0; }
.term-search .ts-prompt { display: flex; align-items: center; padding: 0 .55rem; font-family: var(--mono); color: var(--grn); background: #03070a; border: 1px solid var(--line-2); border-right: 0; }
.term-search input { flex: 1; min-width: 0; background: #03070a; border: 1px solid var(--line-2); color: var(--txt); font-family: var(--mono); font-size: .82rem; padding: .55rem .4rem; outline: none; }
.term-search input:focus { border-color: var(--grn-dim); }
.term-search button { background: transparent; border: 1px solid var(--line-2); color: var(--grn); font-family: var(--mono); font-size: .95rem; padding: 0 .8rem; cursor: pointer; transition: all .15s; }
.term-search button:hover { background: var(--grn); color: #04120b; border-color: var(--grn); }

.label-list, .pop-list, .widget-content ul { list-style: none; margin: 0; padding: 0; font-family: var(--mono); font-size: .82rem; }
.label-list li, .pop-list li, .widget-content ul li { border-bottom: 1px dashed var(--line); }
.label-list li:last-child, .pop-list li:last-child, .widget-content ul li:last-child { border-bottom: 0; }
.label-list a, .pop-list a, .widget-content ul a { display: flex; align-items: center; gap: .5rem; padding: .45rem .2rem; color: var(--txt); }
.label-list a:hover, .pop-list a:hover, .widget-content ul a:hover { color: var(--grn); text-shadow: none; background: var(--grn-dark); }
.label-list .lp, .widget-content ul .lp { color: var(--grn-dim); }
.label-count { margin-left: auto; font-size: .68rem; color: var(--muted); border: 1px solid var(--line); padding: 0 .45rem; border-radius: 2px; }
.pop-list { counter-reset: pop; }
.pop-list li { counter-increment: pop; }
.pop-list a::before { content: counter(pop, decimal-leading-zero); color: var(--grn-dim); font-size: .72rem; opacity: .8; min-width: 1.8rem; }
.pop-list .pop-title { flex: 1; line-height: 1.4; }

.wire-card p { margin: 0 0 .8rem; font-size: .85rem; line-height: 1.65; }
.wire-card p:last-child { margin-bottom: 0; }
.wire-card .wc-line { font-family: var(--mono); font-size: .76rem; color: var(--muted); margin: 0 0 .8rem; }
.wire-card .wc-prompt { color: var(--grn); }
.wire-card a { text-decoration: underline; text-underline-offset: 3px; }

.site-footer { border-top: 1px solid var(--line); background: var(--bg-2); margin-top: 3rem; position: relative; z-index: 1; }
.footer-inner { max-width: var(--w); margin: 0 auto; padding: 2.2rem 1.2rem 0; }
.footer-cols { display: grid; grid-template-columns: 1.6fr 1fr 1.2fr; gap: 1.8rem; padding-bottom: 1.8rem; }
.footer-col h4 { color: var(--grn); font-size: .88rem; margin: 0 0 .9rem; letter-spacing: .06em; }
.footer-col h4::before { content: '$ '; color: var(--grn-dim); }
.footer-col p { color: var(--muted); font-size: .84rem; margin: 0 0 .8rem; line-height: 1.7; }
.footer-col ul { list-style: none; margin: 0; padding: 0; font-family: var(--mono); font-size: .82rem; }
.footer-col li { margin: .42rem 0; }
.footer-col li::before { content: '> '; color: var(--grn-dim); }
.footer-col .sys-line { font-family: var(--mono); font-size: .76rem; color: var(--muted); display: flex; gap: .5rem; margin: .35rem 0; }
.footer-col .sys-line .ok { color: var(--grn); }
.foot-ascii { font-family: var(--mono); color: var(--grn-dim); font-size: .62rem; line-height: 1.25; white-space: pre; text-shadow: var(--glow-soft); margin: 0 0 .8rem; }
.attribution { border-top: 1px dashed var(--line); padding: 1.1rem; text-align: center; font-family: var(--mono); font-size: .74rem; color: var(--muted); }
.attribution a { color: var(--muted); }
.attribution a:hover { color: var(--grn); }
.footer-cols .widget { background: none; border: 0; margin: 0; padding: 0; }
.footer-cols .widget .widget-title { display: none; }
.footer-cols .widget .widget-content { padding: 0; }

.reveal { opacity: 0; transform: translateY(16px); transition: opacity .5s ease, transform .5s ease; }
.reveal.in { opacity: 1; transform: none; }

@media (max-width: 1020px) {
  .layout { grid-template-columns: 1fr; }
  .sidebar { display: grid; grid-template-columns: repeat(2,1fr); gap: 0 1.2rem; align-items: start; }
  .sidebar .widget { break-inside: avoid; }
  .related-grid { grid-template-columns: repeat(2,1fr); }
}
@media (max-width: 860px) {
  .nav-toggle { display: inline-block; }
  .nav-section { order: 3; flex-basis: 100%; margin-left: 0; display: none; border-top: 1px solid var(--line); }
  .site-header.nav-open .nav-section { display: block; }
  .nav-links { flex-direction: column; align-items: stretch; padding: .5rem 0; }
  .nav-links a { display: block; padding: .6rem .2rem; border-bottom: 1px dashed var(--line); }
  .post-card { grid-template-columns: 1fr; }
  .card-thumb { min-height: 0; }
  .footer-cols { grid-template-columns: 1fr; gap: 1.4rem; }
  .foot-ascii { font-size: .55rem; }
}
@media (max-width: 620px) {
  .sidebar { grid-template-columns: 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .hero-body { padding: 1.4rem 1.1rem; }
  .post-header, .post-body, .post-footer { padding-left: 1.1rem; padding-right: 1.1rem; }
  .tagline { display: none; }
}

body.script:
//
(function () {
  'use strict';

  var navToggle = document.querySelector('.nav-toggle');
  var header = document.querySelector('.site-header');
  if (navToggle && header) {
    navToggle.addEventListener('click', function () {
      var open = header.classList.toggle('nav-open');
      navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  var bar = document.getElementById('progress-bar');
  function updateProgress() {
    if (!bar) return;
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';
  }
  document.addEventListener('scroll', updateProgress, { passive: true });
  updateProgress();

  var topBtn = document.getElementById('back-to-top');
  if (topBtn) {
    window.addEventListener('scroll', function () {
      topBtn.classList.toggle('show', window.scrollY > 500);
    }, { passive: true });
    topBtn.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  var revealables = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window && revealables.length) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
      });
    }, { threshold: 0.08 });
    revealables.forEach(function (el) { io.observe(el); });
  } else {
    revealables.forEach(function (el) { el.classList.add('in'); });
  }

  function epBadge(title) {
    var m = /episode\s*(\d+)/i.exec(title || '');
    if (m) return 'EP_' + ('00' + m[1]).slice(-2);
    m = /\bE(\d{1,3})\b/.exec(title || '');
    if (m) return 'EP_' + ('00' + m[1]).slice(-2);
    return '';
  }
  document.querySelectorAll('.post-card').forEach(function (card) {
    var badge = card.querySelector('.card-badge');
    if (badge && !badge.textContent.trim()) {
      var t = card.querySelector('.post-title');
      var label = epBadge(t ? t.textContent : '');
      if (label) { badge.textContent = label; }
      else if (badge.parentNode) { badge.parentNode.removeChild(badge); }
    }
  });

  var rel = null;
  document.querySelectorAll('.related-feed').forEach(function (el) {
    var id = el.id;
    if (!id) return;
    var base = id.replace(/_related$/, '');
    var labelEl = document.getElementById(base + '_related_label');
    var feedEl = document.getElementById(base + '_related_feed');
    if (!labelEl || !feedEl) return;
    var label = labelEl.textContent.trim();
    var home = feedEl.value;
    if (!label || !home) return;
    var grid = el.querySelector('.related-grid');
    if (!grid) return;
    fetch(home + 'feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=4')
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (data) {
        if (!data || !data.feed || !data.feed.entry) return;
        var here = location.href.split('?')[0].split('#')[0];
        var html = '';
        var count = 0;
        data.feed.entry.forEach(function (entry) {
          if (count >= 3) return;
          var link = '#';
          (entry.link || []).forEach(function (l) {
            if (l.rel === 'alternate' && l.type === 'text/html') link = l.href;
          });
          if (link.split('?')[0].split('#')[0] === here) return;
          var title = entry.title && entry.title.$t ? entry.title.$t : 'untitled';
          var thumb = '';
          if (entry.media$thumbnail && entry.media$thumbnail.url) {
            thumb = entry.media$thumbnail.url.replace(/\/s72(-c)?\//, '/s320/');
          }
          var badge = epBadge(title);
          html += '<a class="related-item reveal in" href="' + link + '">' +
            '<span class="ri-thumb">' +
              (thumb ? '<img loading="lazy" src="' + thumb + '" alt="' + title.replace(/"/g, '&quot;') + '">'
                     : '<span class="ri-no">' + (badge || 'FILE') + '</span>') +
            '</span>' +
            '<span class="ri-title">' + title + '</span></a>';
          count++;
        });
        if (html) { grid.innerHTML = html; el.style.display = 'block'; }
      })
      .catch(function () {});
  });

  document.querySelectorAll('.js-year').forEach(function (el) {
    el.textContent = new Date().getFullYear();
  });

  try {
    console.log('%cWIRED://LAIN v1.0%c\n> no matter where you are, everyone is always connected.\n> present day, present time.',
      'color:#3dffa0;font-family:monospace;font-weight:bold;font-size:16px',
      'color:#6f8f82;font-family:monospace');
  } catch (e) {}
})();
//
